Object.assign(SNIP,{"l20shadow": "#include <iostream>\nusing namespace std;\n\nint x = 100;            // biến toàn cục\n\nvoid inX() {\n    cout << x << \"\\n\";  // không có x cục bộ: dùng x toàn cục → 100\n}\n\nint main() {\n    int x = 5;          // x cục bộ CHE KHUẤT x toàn cục bên trong main\n    cout << x << \"\\n\";  // 5\n    inX();              // 100\n    return 0;\n}", "l20block": "#include <iostream>\nusing namespace std;\n\nint main() {\n    int a = 1;              // a sống tới hết main\n    {\n        int b = 2;          // b chỉ sống trong khối { } này\n        cout << a + b;      // dùng được cả a và b\n    }\n    // cout << b;           // LỖI: b đã \"chết\" khi ra khỏi khối\n    return 0;\n}", "l20for": "int tong = 0;                    // khai báo TRƯỚC vòng lặp: còn dùng được sau vòng lặp\nfor (int i = 1; i <= 5; i++) {   // i chỉ sống trong vòng for\n    tong += i;\n}\ncout << tong;                    // đúng\n// cout << i;                    // LỖI: 'i' was not declared in this scope"});PRESET_NOTES["l20"]={"Ví dụ: Biến trong khối { }": "Bấm Từng bước và nhìn khung Bộ nhớ: b xuất hiện khi vào khối { } và biến mất ngay khi ra khỏi khối, còn a vẫn ở đó tới cuối main.", "Ví dụ: Biến của vòng for": "i chỉ có trong Bộ nhớ khi vòng for đang chạy; tong khai báo trước vòng lặp nên còn dùng được để in kết quả.", "Ví dụ: Cùng tên x ở hai hàm": "Hai biến cùng tên x nằm ở hai khung khác nhau trên ngăn xếp (xem cột địa chỉ). gapDoi sửa x của nó, x của main vẫn là 5.", "Ví dụ: Che khuất tên": "main có x cục bộ (5) che khuất x toàn cục (100). inX không có x cục bộ nên dùng x toàn cục. Khung Biến toàn cục hiện riêng phía dưới.", "Ví dụ: Biến cục bộ sinh lại mỗi lần gọi": "demCucBo được tạo mới bằng 0 ở mỗi lần gọi nên lần nào cũng in 1. demToanCuc sống suốt chương trình nên tăng dần 1, 2, 3.", "Lỗi: dùng biến ngoài phạm vi": "i chỉ sống trong vòng for, nên dòng in i sau vòng lặp báo lỗi 'i' was not declared in this scope. Cách sửa: khai báo int i; trước vòng lặp.", "Lỗi: dùng biến trước khi khai báo": "Phạm vi của biến bắt đầu từ dòng khai báo, không phải từ đầu khối. Dòng tong = 10; nằm trước dòng khai báo nên báo lỗi."};EX_HINTS["l20"]=[["tong và dem phải khai báo TRƯỚC vòng lặp: đặt trong vòng lặp thì mỗi lần lặp chúng bị tạo lại bằng 0, và sau vòng lặp không còn để in.", "Chỉ cộng và đếm khi x > 0 (số 0 không phải số dương)."], ["soLanGoi phải là biến toàn cục (khai báo ngoài mọi hàm, phía trên binhPhuong) thì cả binhPhuong và main mới dùng được.", "Nếu khai báo soLanGoi bên trong binhPhuong, nó bị tạo lại bằng 0 ở mỗi lần gọi."], ["lonNhat và viTri khai báo trước vòng lặp để còn in sau vòng lặp.", "Số đầu tiên luôn được nhận làm lớn nhất (i == 1), kể cả khi mọi số đều âm.", "Dùng x > lonNhat (không phải >=) để giữ vị trí ĐẦU TIÊN khi có nhiều số bằng nhau."]];
